body.onloadscript:

	// debugger ;
	// gridObj.detachHeader(0);

	// 헤더 다시 구성
	gridObj.clearAll(true) ;

	// 헤더 1열
	gridObj.setHeader("부서명,인감 구분,합계,완료,#cspan,책임자 승인진행,#cspan,결재진행,#cspan,책임자반려,#cspan,결재반려,#cspan,임시저장,#cspan,증명서,#cspan,#cspan,#cspan,#cspan");
	// 헤더 2열
	gridObj.attachHeader(["#rspan","#rspan","#rspan","전자","실물","전자","실물","전자","실물","전자","실물","전자","실물","전자","실물","발급완료","결재완료","결재진행","결재반려","임시저장"]);
	// 각 헤더 수평 정렬
	gridObj.setColAlign("center,left,center,center,center,center,center,center,center,center,center,center,center,center,center,center,center,center,center,center,center");
	// 각 컬럼 타입 
	gridObj.setColTypes("ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed,ed");
	// 헤더, 그리드, 셀, 로우 css
	gridObj.setStyle("font-color:blue;font-size:16px;","background-color:white;color:black;font-size:14px;","background-color:black;color:white;font-size:14px;", "background-color:black;color:white;font-size:14px;");

	gridObj.enableAlterCss("even","uneven");
	gridObj.init() ;

    doQuery();

userscript.function:

        	if( count == 0 ) return ;
        	// 합계 컬럼 계산 
        	for(var row=1;row <= count;row++) {
        		var sum = 0 ;
        		for (var col=3;col<=19;col++) {
        			sum += Number(gridObj.cells(row, col).getValue()) ;
        		}

        		gridObj.cells(row, 2).setValue(sum) ;
        		// gridObj.cells(row, 3).setStyle("background-color:black;color:white;font-size:16;");

       		}

            var dept_column = 0  ; //  gridObj.getColIndexById("DEPT_NAME") 이거 안됨. clearAll 해서 그런 것 같음 

            var dept_name = "" ;  // 라인의 부서 명 

            var old_dept = gridObj.cells(1, dept_column).getValue();  // 첫번째 부서명 으로 초기화 

        	var span_height = 1 ;  // 병합 크기 초기화
        	var span_start = 1 ;   // 병합 시작 라인 번호 초기화

        	var row = 1;  // 그리드 데이터 시작 번호
        	var add_row = 0 ;  // 추가된 라인 초기화 ( 소계 추가 )
        	var max_row = count ;  // 전체 라인 초기화 , 처음에는 쿼리 카운트가 됨

        	while(true) {

        		dept_name = gridObj.cells(row, dept_column).getValue();  // 현재 라인의 부서명 

        		// 부서가 같지 않으면 소계를 위한 라인을 추가한다.
        		if( dept_name != old_dept ) {    

        			max_row ++ ;   // 전체 라인 갯수 증가
		        	gridObj.addRow(max_row, '', row + add_row - 1, "parent_row",'',true);   // 바뀐 부서 바로 앞 라인에 라인 추가 

		        	add_row ++ ;   // 추가된 라인 갯수 증가
		            gridObj.cells(max_row, dept_column+1).setValue( "소계") ;   // 이름 셋업
		        	gridObj.setCellTextStyle(max_row, dept_column+1,"background-color: #66FF66;color: black;font-weight: bold; ");

		            gridObj.setRowspan(span_start, dept_column, span_height);   //  같은 부서끼리 셀 병합

		            // 소계 계산 
		            for (var col=2 ; col <= 19 ; col++) {
		            	var sum = 0 ;
		            	for( var col_ind = span_start ; col_ind < span_start + span_height - 1 ; col_ind ++ )  
        					sum += Number(gridObj.cells(col_ind, col).getValue()) ;
        				if( sum > 0 ) 
        					gridObj.cells(max_row,col).setValue(sum) ;
        				gridObj.setCellTextStyle(max_row, col,"background-color:#66FF66;color: black;font-weight: bold;");

        			}	

		            old_dept = dept_name ;   // 부서 이름 리셋 
		            span_height = 2 ;    // 병합 칸 리셋 - 기본 2칸에서 시작 
		            span_start = row ;   // 병합 시작 라인 번호 리셋
	            }
	            else {
	            	span_height ++;
            	}

            	row ++ ;

            	if( row > count) break ;

            }

            max_row++ ;   // 마지막 부서 소계 추가 하기 위한 라인 추가 
            gridObj.addRow(max_row, '', max_row ); 
            gridObj.cells(max_row, dept_column+1).setValue( "소계") ;   // 마지막 부서 소계 
            gridObj.setCellTextStyle(max_row, dept_column+1,"background-color: #66FF66; color: black;font-weight: bold;");
            gridObj.setRowspan(span_start, dept_column, span_height);   // 마지막 부서 셀 병합

            // 마지막 부서 소계 계산 
            for (var col=2 ; col <= 19 ; col++) {
            	var sum = 0 ;
            	for( var col_ind = span_start ; col_ind < span_start + span_height - 1 ; col_ind ++ )  
      					sum += Number(gridObj.cells(col_ind, col).getValue()) ;
      				if( sum > 0 ) 
      					gridObj.cells(max_row,col).setValue(sum) ;
					gridObj.setCellTextStyle(max_row, col,"background-color: #66FF66;color: black; font-weight: bold;");      					
      		}	

            max_row++ ;   // 전체 합계 추가 하기 위한 라인 추가 
            gridObj.addRow(max_row, '', max_row ); 


            gridObj.cells(max_row, dept_column).setValue( "전체 합계") ;   // 전체 합계 

            // debugger ;
            // 전체 합계 계산 
            for (var col=2 ; col <= 19 ; col++) {
            	var sum = 0 ;
            	for( var col_ind = 1 ; col_ind <= count ; col_ind ++ )
					sum += Number(gridObj.cells(col_ind, col).getValue()) ;
      				if( sum > 0 ) 
      					gridObj.cells(max_row,col).setValue(sum) ;

    		}	
    		gridObj.setRowTextStyle(max_row, "background-color: yellow;color: red; font-weight: bold;font-size:16px");
            gridObj.enableColSpan(true);
            gridObj.setColspan(max_row,dept_column,2) ;  // 전체 합계 셀 컬럼 병합
            gridObj.editStop(true) ;
